class DINOv2Encoder(nn.Module):
    "Frozen DINOv2-B encoder wrapped to output EncoderOutput (CLS=L0, patch tokens=L1)."
    def __init__(self, model_name='facebook/dinov2-base'):
        super().__init__()
        from transformers import AutoModel
        self.model = AutoModel.from_pretrained(model_name)
        for p in self.parameters(): p.requires_grad = False
        self.eval()

    def forward(self, x):
        # x: (B, 3, 126, 126)
        outputs = self.model(pixel_values=x)
        hidden = outputs.last_hidden_state  # (B, 82, 768): 1 CLS + 81 patch tokens
        B, N_total, D = hidden.shape
        N_patches = N_total - 1  # 81 = 9×9
        H = W = int(N_patches ** 0.5)  # 9

        cls_emb   = hidden[:, 0:1, :]  # (B, 1, 768)
        patch_emb = hidden[:, 1:,  :]  # (B, 81, 768)

        device = x.device
        rows      = torch.arange(H, device=device).repeat_interleave(W)
        cols      = torch.arange(W, device=device).repeat(H)
        patch_pos = torch.stack([rows, cols], dim=-1)          # (81, 2)
        cls_pos   = torch.full((1, 2), -1, device=device)     # (1, 2)
        full_pos  = torch.cat([cls_pos, patch_pos], dim=0)    # (82, 2)

        full_non_empty = torch.ones(B, N_total, dtype=torch.bool, device=device)
        mae_mask       = torch.zeros(N_total,   dtype=torch.bool, device=device)

        cls_ps   = PatchState(emb=cls_emb,   pos=cls_pos,   non_empty=full_non_empty[:, 0:1], mae_mask=mae_mask[0:1])
        patch_ps = PatchState(emb=patch_emb, pos=patch_pos, non_empty=full_non_empty[:, 1:],  mae_mask=mae_mask[1:])
        return EncoderOutput(patches=HierarchicalPatchState(levels=[cls_ps, patch_ps]),
                             full_pos=full_pos, full_non_empty=full_non_empty, mae_mask=mae_mask)

# %% ../nbs/09_train_dec.ipynb #61dd1ef1
def setup_tstate(cfg, device, decoder, encoder=None, extra_params=None):
    "Training_state: Losses, Optimizers, Schedulers, AMP Scalers"
    enc_ft_lr = cfg.training.get('enc_ft_lr', 0)
    opt_enc = (torch.optim.AdamW(encoder.parameters(), lr=enc_ft_lr)
               if (encoder is not None and enc_ft_lr > 0) else None)
    dec_params = list(decoder.parameters()) + (extra_params or [])
    opt_dec = torch.optim.AdamW(dec_params, lr=cfg.training.dec_lr)
    scheduler = torch.optim.lr_scheduler.OneCycleLR(opt_dec, max_lr=cfg.training.dec_lr, steps_per_epoch=1, epochs=cfg.training.dec_epochs, div_factor=4)
    scheduler_enc = (torch.optim.lr_scheduler.OneCycleLR(opt_enc, max_lr=enc_ft_lr, steps_per_epoch=1, epochs=max(1, cfg.training.dec_epochs))
                     if opt_enc is not None else None)
    scaler_dec = torch.amp.GradScaler()
    TrainState = namedtuple('TrainState', ['opt_enc', 'opt_dec', 'scaler_dec', 'scheduler', 'scheduler_enc'])
    return TrainState(opt_enc, opt_dec, scaler_dec, scheduler, scheduler_enc)

# %% ../nbs/09_train_dec.ipynb #102f0438
def get_embeddings_batch(batch, encoder, device='cuda', allow_grad=False):
    "Encode a raw image batch; returns (enc_out, img_real, note_weights). img_real is 1ch reconstruction target."
    img = batch['img'].to(device)
    img_real = batch['img_target'].to(device) if 'img_target' in batch else img
    note_weights = batch['note_weights'].to(device) if 'note_weights' in batch else None
    with (nullcontext() if allow_grad else torch.no_grad()), torch.autocast(device_type='cuda', dtype=torch.bfloat16):
        enc_out = encoder(img)
    return enc_out, img_real, note_weights

# %% ../nbs/09_train_dec.ipynb #928a8d39
def train_step(epoch, enc_out, img_real, decoder,
            tstate,  # named tuple containing optimizers, loss fns, scalers
            cfg,    # config
            note_weights=None,
            mask_tokens=None,
            ):
    "training step for decoder (and optionally encoder when enc_ft_lr > 0)"
    decoder.train()
    if tstate.opt_enc is not None: tstate.opt_enc.zero_grad()
    tstate.opt_dec.zero_grad()
    enc_out = mask_enc_out(enc_out,
                           mask_ratio=cfg.training.get('emb_mask_ratio', 0.0),
                           mr_level_fac=cfg.training.get('emb_mask_level_fac', 1.25),
                           mask_levels=cfg.training.get('mask_levels', None),
                           mask_tokens=mask_tokens)
    with torch.autocast(device_type='cuda', dtype=torch.bfloat16):
        loss_dict = calc_dec_loss(decoder, enc_out, img_real, pos_weight=cfg.training.get('pos_weight',1.0), note_weights=note_weights)
    tstate.scaler_dec.scale(loss_dict['dec']).backward()
    tstate.scaler_dec.unscale_(tstate.opt_dec)
    torch.nn.utils.clip_grad_norm_(decoder.parameters(), max_norm=1.0)
    if tstate.opt_enc is not None:
        tstate.scaler_dec.unscale_(tstate.opt_enc)
        torch.nn.utils.clip_grad_norm_(decoder.parameters(), max_norm=1.0)
        tstate.scaler_dec.step(tstate.opt_enc)
    tstate.scaler_dec.step(tstate.opt_dec)
    tstate.scaler_dec.update()
    return loss_dict, loss_dict['recon']

