import pickle, glob as _glob

def load_pca_models(pca_dir, n_levels, fine_levels=None, fine_n_components=None,
                    n_per_lvl=None):
    """Load sklearn PCA models from pca_dir for levels 0..n_levels-1.

    Auto-discovers PKL files by globbing for pca_L{i}_n*.pkl — no need to specify
    the exact component count.  When multiple files exist for a level (e.g. from
    different fitpca runs), the most recently modified one is used.
    n_per_lvl / fine_levels / fine_n_components accepted for backwards compatibility.
    """
    pca_dir = os.path.expandvars(os.path.expanduser(str(pca_dir)))
    pca_models = {}
    for i in range(n_levels):
        matches = _glob.glob(os.path.join(pca_dir, f'pca_L{i}_n*.pkl'))
        if not matches:
            continue
        path = max(matches, key=os.path.getmtime)  # newest file wins
        if len(matches) > 1:
            print(f"  load_pca_models L{i}: {len(matches)} PKL files found; using newest: {os.path.basename(path)}")
        with open(path, 'rb') as f:
            pca_models[i] = pickle.load(f)
    return pca_models

def pca_roundtrip_enc_out(enc_out, pca_models, n_aug_levels, device, noise_std=0.0):
    "Apply PCA compress→decompress to the first n_aug_levels levels of enc_out, with optional noise injection."
    new_levels = []
    for i, lvl in enumerate(enc_out.patches.levels):
        if i < n_aug_levels and i in pca_models:
            B, N, D = lvl.emb.shape
            pca = pca_models[i]
            flat = lvl.emb.float().cpu().numpy().reshape(B * N, D)
            flat_rt = pca.inverse_transform(pca.transform(flat))
            emb_rt = torch.tensor(flat_rt.reshape(B, N, D), dtype=lvl.emb.dtype, device=device)
            if noise_std > 0.0:
                emb_rt = emb_rt + torch.randn_like(emb_rt) * noise_std
            new_levels.append(PatchState(emb=emb_rt, pos=lvl.pos, non_empty=lvl.non_empty, mae_mask=lvl.mae_mask))
        else:
            new_levels.append(lvl)
    return EncoderOutput(
        patches=HierarchicalPatchState(levels=new_levels),
        full_pos=enc_out.full_pos, full_non_empty=enc_out.full_non_empty, mae_mask=enc_out.mae_mask)

# %% ../nbs/09_train_dec.ipynb #198855af
def train(cfg: DictConfig):
    dict_test = dict(cfg) # force resolution of required fields (e.g. tag=???)
    device = 'cuda' if torch.cuda.is_available() else 'mps' if torch.backends.mps.is_available() else 'cpu'
    cjprint(f"config file: {HydraConfig.get().job.config_name}\nconfig: {cfg}\ndevice = {device}",color="green")
    set_seed()
    preencoded = cfg.get('preencoded', False)

    train_dl, val_dl  = setup_dataloaders(cfg, preencoded)
    encoder, decoder  = setup_models(cfg, device, preencoded)
    patch_size = cfg.model.get('patch_size', cfg.model.get('patch_h', 16))

    mask_tokens = None
    if cfg.training.get('emb_mask_ratio', 0.0) > 0 or cfg.training.get('mask_levels', None):
        n_levels = len(cfg.model.depths)
        dims = [cfg.model.embed_dim * (2 ** (n_levels - 1 - i)) for i in range(n_levels)]
        mask_tokens = MaskTokens(dims).to(device)

    pos_cache = None
    if preencoded:
        from midi_rae.swin import SwinEncoder
        _enc = SwinEncoder(
            img_height=cfg.data.image_size, img_width=cfg.data.image_size,
            patch_h=cfg.model.patch_h, patch_w=cfg.model.patch_w,
            embed_dim=cfg.model.embed_dim, depths=cfg.model.depths,
            num_heads=cfg.model.num_heads, window_size=cfg.model.window_size,
            mlp_ratio=cfg.model.mlp_ratio, drop_path_rate=cfg.model.drop_path_rate,
        ).to(device)
        _enc = load_checkpoint(_enc, cfg.encoder_ckpt)
        pos_cache = get_pos_cache(_enc, cfg.data.image_size, device)
        del _enc

    pca_models = None
    pca_aug_levels   = cfg.training.get('pca_aug_levels', 6)
    pca_aug_prob     = cfg.training.get('pca_aug_prob', 1.0)
    emb_noise_std    = cfg.training.get('emb_noise_std', 0.0)  # latent noise applied regardless of PCA
    if cfg.training.get('pca_aug', False):
        raw_npl = cfg.training.get('pca_n_per_lvl', None)
        n_per_lvl = list(raw_npl) if raw_npl is not None else None
        raw_fn = cfg.training.get('pca_fine_n_components', None)
        fine_n_components = (list(raw_fn) if hasattr(raw_fn, '__iter__') else int(raw_fn)) if raw_fn is not None else None
        raw_fl = cfg.training.get('pca_fine_levels', None)
        fine_levels = list(raw_fl) if raw_fl is not None else None
        pca_models = load_pca_models(cfg.training.pca_dir, pca_aug_levels,
                                     fine_levels=fine_levels, fine_n_components=fine_n_components,
                                     n_per_lvl=n_per_lvl)
        cjprint(f"PCA roundtrip enabled: {pca_aug_levels} levels, n_per_lvl={n_per_lvl}, prob={pca_aug_prob}, dir={cfg.training.pca_dir}", color='magenta')
    if emb_noise_std > 0:
        cjprint(f"Latent noising enabled: emb_noise_std={emb_noise_std}", color='magenta')

    tstate = setup_tstate(cfg, device, decoder, encoder=encoder,
                          extra_params=list(mask_tokens.parameters()) if mask_tokens else None)

    if cfg.training.get('dec_init_ckpt', None):
        decoder = load_checkpoint(decoder, os.path.expandvars(os.path.expanduser(cfg.training.dec_init_ckpt)))
        cjprint(f"Loaded decoder init weights from {cfg.training.dec_init_ckpt}", color='magenta')

    if (cfg.get('checkpoint', False)):
        decoder, ckpt = load_checkpoint(decoder, cfg.get('checkpoint',None), return_all=True)
        tstate.opt_dec.load_state_dict(ckpt['optimizer_state_dict'])

    if not(cfg.get('no_wandb', False)):
        wandb.init(project='dec-'+cfg.wandb.project, config=dict(cfg))
        wandb.define_metric("epoch")
        wandb.define_metric("*", step_metric="epoch")
        wandb.run.name = f"{cfg.tag}_{wandb.run.name}"

    emb_mask_ratio = cfg.training.get('emb_mask_ratio', 0.0)
    mask_levels     = cfg.training.get('mask_levels', None)

    global_step = 0
    viz_every = 2
    best_val_loss = float('inf')
    for epoch in range(1, cfg.training.dec_epochs + 1):
        train_loss = 0
        for batch in tqdm(train_dl, desc=f'Epoch {epoch}/{cfg.training.dec_epochs}'):
            global_step += 1
            if preencoded:
                emb_levels, img_real = batch
                img_real = img_real.to(device).float()
                enc_out = emb_levels_to_enc_out(emb_levels, pos_cache, device)
                note_weights = None
            else:
                enc_out, img_real, note_weights = get_embeddings_batch(batch, encoder, device,
                                                                        allow_grad=(tstate.opt_enc is not None))
            if pca_models is not None and torch.rand(1).item() < pca_aug_prob:
                enc_out = pca_roundtrip_enc_out(enc_out, pca_models, pca_aug_levels, device, noise_std=0.0)
            if emb_noise_std > 0:
                enc_out = add_noise_to_enc_out(enc_out, emb_noise_std)
            losses, img_recon = train_step(epoch, enc_out, img_real, decoder, tstate, cfg, note_weights=note_weights, mask_tokens=mask_tokens)
            train_loss += losses['dec'].item()

        train_loss /= len(train_dl)

        decoder.eval()
        with torch.no_grad():
            val_loss = 0
            for batch in val_dl:
                with torch.autocast(device_type='cuda', dtype=torch.bfloat16):
                    if preencoded:
                        emb_levels, img_real = batch
                        img_real = img_real.to(device).float()
                        enc_out = emb_levels_to_enc_out(emb_levels, pos_cache, device)
                    else:
                        enc_out, img_real, _ = get_embeddings_batch(batch, encoder, device)
                    # no noise during val — clean eval
                    if pca_models is not None:
                        enc_out = pca_roundtrip_enc_out(enc_out, pca_models, pca_aug_levels, device, noise_std=0.0)
                    enc_out = mask_enc_out(enc_out, mask_ratio=emb_mask_ratio,
                                           mr_level_fac=cfg.training.get('emb_mask_level_fac', 1.25),
                                           mask_levels=mask_levels, mask_tokens=mask_tokens)
                    loss_dict = calc_dec_loss(decoder, enc_out, img_real, pos_weight=cfg.training.get('pos_weight',1.0), note_weights=note_weights)
                    loss_dec, img_recon = loss_dict['dec'], loss_dict['recon']
                val_loss += loss_dec.item()
            val_loss /= len(val_dl)
            if val_loss < best_val_loss: best_val_loss = val_loss
            print(f'Epoch {epoch}: train_loss={train_loss:.6f} val_loss={val_loss:.6f}, best_val_loss={best_val_loss:.6f}')

            if wandb.run is not None:
                wandb.log({
                    'train_dec': train_loss, 'train_bce': to_scalar(losses['bce']),      'train_mse': to_scalar(losses['mse']),
                    'val_dec':     val_loss,   'val_bce': to_scalar(loss_dict['bce']), 'val_mse': to_scalar(loss_dict['mse']),
                    'epoch': epoch, 'lr_dec': tstate.opt_dec.param_groups[0]['lr'],})
            if epoch % viz_every == 0:
                *_, clean_evals = viz_mae_recon(img_recon, img_real, epoch=epoch, patch_size=patch_size, return_maps=True)
                log_extra = {'F1_clean': clean_evals['f1'], 'epoch': epoch}
                if emb_mask_ratio > 0:
                    masked_enc = mask_enc_out(enc_out,
                                             mask_ratio=emb_mask_ratio,
                                             mr_level_fac=cfg.training.get('emb_mask_level_fac', 1.25),
                                             mask_levels=mask_levels,
                                             mask_tokens=mask_tokens)
                    with torch.autocast(device_type='cuda', dtype=torch.bfloat16):
                        m_ld = calc_dec_loss(decoder, masked_enc, img_real, pos_weight=cfg.training.get('pos_weight', 1.0))
                    *_, masked_evals = viz_mae_recon(m_ld['recon'], img_real, epoch=epoch, patch_size=patch_size, return_maps=True)
                    log_extra['F1_masked'] = masked_evals['f1']
                    print(f"  F1_clean={clean_evals['f1']:.4f}  F1_masked={masked_evals['f1']:.4f}")
                    del masked_evals
                if wandb.run is not None: wandb.log(log_extra)
                del clean_evals
            gc.collect()

        models_to_save = (decoder, encoder) if (encoder is not None and encoder.training) else decoder
        save_checkpoint(models_to_save, epoch, val_loss, cfg, optimizer=tstate.opt_dec, tag=cfg.tag)
        freemem()
        tstate.scheduler.step()
        if tstate.scheduler_enc is not None: tstate.scheduler_enc.step()

    wandb.finish()
    return best_val_loss

